sys_script.script:
(function executeRule(current, previous /* null when async */) {

    var handoffType = current.getValue('handoff_type');

    // Department Transfer
    if (handoffType == 'Department Transfer') {

        if (!current.from_department.nil() &&
            !current.to_department.nil() &&
            current.from_department.getValue() ==
            current.to_department.getValue()) {

            gs.addErrorMessage(
                'From Department and To Department cannot be the same for a Department Transfer.'
            );

            current.setAbortAction(true);
            return;
        }
    }

    // Ward Transfer
    if (handoffType == 'Ward Transfer') {

        if (!current.from_ward.nil() &&
            !current.to_ward.nil() &&
            current.from_ward.getValue() ==
            current.to_ward.getValue()) {

            gs.addErrorMessage(
                'From Ward and To Ward cannot be the same for a Ward Transfer.'
            );

            current.setAbortAction(true);
            return;
        }
    }

    // Bed movement
    if (!current.from_bed.nil() &&
        !current.to_bed.nil() &&
        current.from_bed.getValue() ==
        current.to_bed.getValue()) {

        gs.addErrorMessage(
            'From Bed and To Bed cannot be the same.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
